// Validate and format RAG response
const input = $input.first().json;
let response = input.output || input.response || input.text || input.content || '';

if (typeof response === 'object') {
  response = response.text || response.content || response.message || JSON.stringify(response);
}

if (!response || response.trim().length === 0) {
  response = 'I could not find relevant information to answer your question. Please try rephrasing or ask about a different topic.';
}

// Check if response cites sources
const hasCitations = /\[\d+\]/.test(response);
if (!hasCitations) {
  response += '\n\n_Note: No specific source citations were generated for this response._';
}

return [{
  json: {
    response: response,
    sessionId: input.sessionId || '',
    query: input.query || '',
    intent: 'RAG_QUERY'
  }
}];
